## 25.8 Python example: threshold metrics by group

The interactive above uses the same mathematical idea as the following Python simulation.  We generate scores $S$, choose a threshold $t$, and compute group-wise rates.

::: {.cell execution_count=2}
``` {.python .cell-code}
import numpy as np
import pandas as pd

rng = np.random.default_rng(2025)

nA = 400
nB = 400
YA = rng.binomial(1, 0.45, size=nA)
YB = rng.binomial(1, 0.30, size=nB)

def clipped_normal(mean, sd, size):
    return np.clip(rng.normal(mean, sd, size=size), 0.01, 0.99)

SA = np.where(YA == 1, clipped_normal(0.70, 0.14, nA), clipped_normal(0.32, 0.15, nA))
SB = np.where(YB == 1, clipped_normal(0.64, 0.15, nB), clipped_normal(0.30, 0.15, nB))

scores = pd.DataFrame({
    "group": np.r_[np.repeat("A", nA), np.repeat("B", nB)],
    "y": np.r_[YA, YB],
    "score": np.r_[SA, SB]
})

def threshold_report(df, threshold):
    out = []
    for g, sub in df.groupby("group"):
        y = sub["y"].to_numpy()
        yhat = (sub["score"].to_numpy() >= threshold).astype(int)
        tp = ((yhat == 1) & (y == 1)).sum()
        fp = ((yhat == 1) & (y == 0)).sum()
        fn = ((yhat == 0) & (y == 1)).sum()
        tn = ((yhat == 0) & (y == 0)).sum()
        out.append({
            "group": g,
            "base_rate": y.mean(),
            "selection_rate": yhat.mean(),
            "TPR": tp / (tp + fn),
            "FPR": fp / (fp + tn),
            "PPV": tp / (tp + fp) if tp + fp > 0 else np.nan,
            "accuracy": (tp + tn) / len(sub)
        })
    return pd.DataFrame(out)

threshold_report(scores, threshold=0.50)
```

