# A small toy embedding audit.  These numbers are artificial and for pedagogy only.
emb = {
    "nurse": np.array([0.10, 0.80]),
    "engineer": np.array([0.80, 0.10]),
    "teacher": np.array([0.20, 0.70]),
    "programmer": np.array([0.75, 0.20]),
    "care": np.array([0.00, 1.00]),
    "family": np.array([0.10, 0.95]),
    "logic": np.array([1.00, 0.00]),
    "machine": np.array([0.95, 0.10]),
